functions.showGuidedRedlines:
function showGuidedRedlines(eli) {
  eli = eli || window.eli;
  if (!eli) return;
  var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
  var NAVY = "#122036", GOLD = "#c9a227", GOLDTX = "#3a2e07";
  var MAX_REVISIONS = 60;       // bound — long docs note the cap
  var AI_CONCURRENCY = 3;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _mount(el) {
    if (typeof window._eliMountOverlay === "function") window._eliMountOverlay(el);
    else document.body.appendChild(el);
  }
  function _parseJSON(raw) {
    if (!raw) return null;
    var s = String(raw).trim();
    var f = s.indexOf("```");
    if (f !== -1) { s = s.replace(/```json/gi, "").replace(/```/g, "").trim(); }
    var a = s.indexOf("{"), b = s.lastIndexOf("}");
    if (a !== -1 && b !== -1 && b > a) s = s.slice(a, b + 1);
    try { return JSON.parse(s); } catch (_e) { return null; }
  }
  // Severity → light palette (dialogs are light in both themes).
  function _sevStyle(sevRaw) {
    var s = String(sevRaw || "").toLowerCase();
    if (s.indexOf("dealbreak") !== -1) return { bg: "#fdecec", fg: "#b91c1c", icon: "alert-octagon" };
    if (s.indexOf("silent") !== -1 || s.indexOf("deletion") !== -1) return { bg: "#e8f1fb", fg: "#1e40af", icon: "trash-x" };
    if (s.indexOf("push") !== -1) return { bg: "#fdf3e3", fg: "#b45309", icon: "flag" };
    if (s.indexOf("accept") !== -1 || s.indexOf("cosmetic") !== -1) return { bg: "#e9f6ee", fg: "#15803d", icon: "check" };
    return { bg: "#f1f5f9", fg: "#475569", icon: "info-circle" };
  }
  function _niBadge(dir) {
    var d = String(dir || "").toLowerCase();
    if (d === "them") return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:700;padding:3px 9px;border-radius:6px;background:#fdecec;color:#b91c1c;">Favors them</span>';
    if (d === "us") return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:700;padding:3px 9px;border-radius:6px;background:#e9f6ee;color:#15803d;">Favors us</span>';
    return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:700;padding:3px 9px;border-radius:6px;background:#f1f5f9;color:#475569;">Neutral</span>';
  }
  function _pill(bg, fg, txt) {
    return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:600;padding:3px 9px;border-radius:6px;background:' + bg + ';color:' + fg + ';">' + _esc(txt) + '</span>';
  }
  function _dot(sev) {
    var c = String(sev || "").toLowerCase().indexOf("high") !== -1 ? "#b91c1c"
      : (String(sev || "").toLowerCase().indexOf("med") !== -1 ? "#b45309" : "#94a3b8");
    return '<span style="width:8px;height:8px;border-radius:50%;background:' + c + ';flex-shrink:0;margin-top:5px;"></span>';
  }
  // Pull a leading clause number ("9.2", "Article 9") off a heading/paragraph.
  function _leadingNumber(t) {
    var m = String(t || "").trim().match(/^((article|section|exhibit|schedule|appendix)\s+)?(\d+(\.\d+)*)\b/i);
    if (!m) return "";
    var word = m[2] ? (m[2].charAt(0).toUpperCase() + m[2].slice(1).toLowerCase() + " ") : "";
    return (word + m[3]).trim();
  }
  function _stripNumber(t) {
    var s = String(t || "").trim();
    var out = s.replace(/^((article|section|exhibit|schedule|appendix)\s+)?\d+(\.\d+)*[\s.):–—\-]*/i, "").trim();
    return out || s;
  }

  // ─── Overlay scaffold ───────────────────────────────────────────────
  var existing = document.getElementById("guidedRedlinesOverlay");
  if (existing) existing.remove();
  var overlay = document.createElement("div");
  overlay.id = "guidedRedlinesOverlay";
  // Full-screen takeover — fills the entire taskpane viewport.
  overlay.style.cssText =
    "position:fixed;inset:0;z-index:99999;background:#fff;display:flex;font-family:Inter,'Segoe UI',system-ui,sans-serif;";
  var box = document.createElement("div");
  box.style.cssText =
    "background:#fff;width:100%;height:100%;display:flex;flex-direction:column;overflow:hidden;";
  overlay.appendChild(box);

  var header = document.createElement("div");
  header.style.cssText = "background:" + NAVY + ";border-top:3px solid " + GOLD + ";padding:13px 20px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-shrink:0;";
  header.innerHTML =
    '<div><div style="font-size:10px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:' + GOLD + ';">Review redlines · guided</div>' +
    '<div style="font-family:Georgia,serif;font-size:16px;color:#fff;margin-top:3px;" id="grdTitle">Guided redline review <span style="font-family:Inter,sans-serif;font-size:10px;font-weight:700;background:#1e2f4a;color:#bcd3ee;padding:2px 8px;border-radius:6px;vertical-align:middle;">EXPERIMENTAL</span></div></div>' +
    '<button id="grdClose" style="background:rgba(255,255,255,0.16);border:1px solid rgba(255,255,255,0.4);color:#fff;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;border-radius:6px;flex-shrink:0;">✕ Close</button>';
  box.appendChild(header);

  var progWrap = document.createElement("div");
  progWrap.style.cssText = "padding:10px 20px 4px;flex-shrink:0;display:none;";
  progWrap.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#64748b;margin-bottom:6px;">' +
      '<span id="grdLabel" style="font-weight:700;color:#0f172a;"></span><span id="grdDecided"></span></div>' +
    '<div style="height:6px;background:#eef2f6;border-radius:999px;overflow:hidden;"><div id="grdBar" style="height:100%;width:0%;background:' + GOLD + ';transition:width .25s;"></div></div>';
  box.appendChild(progWrap);

  var body = document.createElement("div");
  body.style.cssText = "flex:1 1 auto;overflow-y:auto;padding:16px 20px;background:#f8fafc;color:#1e293b;font-size:13px;";
  box.appendChild(body);

  var footer = document.createElement("div");
  footer.style.cssText = "padding:11px 20px;background:#f1f5f9;border-top:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-shrink:0;display:none;";
  footer.innerHTML =
    '<button id="grdBack" style="font-size:12.5px;font-weight:600;padding:8px 14px;border-radius:8px;border:1px solid #cbd5e1;background:#fff;color:#475569;cursor:pointer;">← Back</button>' +
    '<span id="grdPos" style="font-size:12px;color:#94a3b8;"></span>' +
    '<button id="grdNext" style="font-size:12.5px;font-weight:600;padding:8px 14px;border-radius:8px;border:1px solid #cbd5e1;background:#fff;color:#475569;cursor:pointer;">Next →</button>';
  box.appendChild(footer);
  _mount(overlay);

  var labelEl = header.parentNode.querySelector("#grdLabel");
  var barEl = box.querySelector("#grdBar");
  var decidedEl = box.querySelector("#grdDecided");
  var posEl = box.querySelector("#grdPos");
  var backBtn = box.querySelector("#grdBack");
  var nextBtn = box.querySelector("#grdNext");
  function _close() { overlay.remove(); try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "scanning") eli.fsm.transition("idle"); } catch (_e) {} }
  box.querySelector("#grdClose").onclick = _close;
  overlay.onclick = function (e) { if (e.target === overlay) _close(); };

  // ─── State ──────────────────────────────────────────────────────────
  var revisions = [], idx = 0, view = "changed", revising = false, decisions = [], _locatedIdx = -1;

  // ─── Select the current clause in Word (best-effort) ────────────────
  // Anchor on the longest UNCHANGED phrase in the revision (present in the
  // doc regardless of markup); fall back to the new/old text. Search +
  // select so Word scrolls the clause into view and highlights it.
  function _anchorFor(rev) {
    var best = "";
    (rev.tokens || []).forEach(function (tk) {
      if (tk[0] === "norm") { var t = tk[1].replace(/\s+/g, " ").trim(); if (t.length > best.length) best = t; }
    });
    if (best.length >= 14) return best.slice(0, 120);
    var r = (rev.resolved || "").replace(/\s+/g, " ").trim();
    if (r.length >= 8) return r.slice(0, 120);
    return (rev.original || "").replace(/\s+/g, " ").trim().slice(0, 120);
  }
  function _locate(rev) {
    if (!eli.host || typeof eli.host.runRaw !== "function") return;
    var needle = _anchorFor(rev);
    if (!needle || needle.length < 4) return;
    eli.host.runRaw("guided_redlines.locate", function (context) {
      var res = context.document.body.search(needle, { matchCase: false, ignorePunct: true });
      res.load("items");
      return context.sync().then(function () {
        if (res.items && res.items.length) { res.items[0].select(); return context.sync(); }
      });
    }).catch(function () { /* tolerate — locate is best-effort */ });
  }

  // ─── Start screen ───────────────────────────────────────────────────
  function _renderStart() {
    progWrap.style.display = "none";
    footer.style.display = "none";
    body.innerHTML =
      '<div style="text-align:center;padding:34px 20px;">' +
        '<div style="font-size:34px;color:' + GOLD + ';line-height:1;">⚖</div>' +
        '<div style="font-family:Georgia,serif;font-size:19px;color:#0f172a;margin-top:12px;">Walk every revision, one at a time</div>' +
        '<div style="font-size:13px;color:#64748b;line-height:1.6;margin-top:8px;max-width:520px;margin-left:auto;margin-right:auto;">' +
          'ELI reads each tracked change — including paragraph rewrites — and shows the net impact, an AI audit of what materially changed, and any team guidance. You accept, reject, or revise each.' +
        '</div>' +
        '<div style="font-size:11.5px;color:#94a3b8;margin-top:10px;">Experimental · your eyes only · read-only — this never changes your document.</div>' +
        '<button id="grdScan" style="margin-top:20px;padding:11px 22px;border:none;border-radius:8px;background:' + GOLD + ';color:' + GOLDTX + ';font-size:13px;font-weight:800;cursor:pointer;">Scan tracked changes</button>' +
        '<div id="grdScanStatus" style="font-size:12px;color:#64748b;margin-top:14px;min-height:18px;"></div>' +
      '</div>';
    box.querySelector("#grdScan").onclick = _scan;
  }
  function _status(msg, color) {
    var el = box.querySelector("#grdScanStatus");
    if (el) el.innerHTML = '<span style="color:' + (color || "#64748b") + ';">' + _esc(msg) + '</span>';
  }

  // ─── Scan — read body OOXML, parse paragraph-scale revisions ─────────
  function _scan() {
    var btn = box.querySelector("#grdScan");
    if (btn) { btn.disabled = true; btn.style.opacity = "0.55"; }
    _status("Reading tracked changes…");
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      _status("Host unavailable (eli.host.runRaw missing).", "#b91c1c"); return;
    }
    eli.host.runRaw("guided_redlines.scan", function (context) {
      var ooxml = context.document.body.getOoxml();
      return context.sync().then(function () { return ooxml.value || ""; });
    }).then(function (xml) {
      var revs = _parseRevisions(xml);
      if (!revs.length) {
        _status("No tracked changes found in this document.", "#b45309");
        if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
        return;
      }
      var capped = revs.length > MAX_REVISIONS;
      revisions = revs.slice(0, MAX_REVISIONS);
      decisions = revisions.map(function () { return null; });
      _status("Found " + revs.length + " revision" + (revs.length === 1 ? "" : "s") +
        (capped ? " (auditing first " + MAX_REVISIONS + ")" : "") + " · auditing…", "#1e40af");
      _auditAll(function (d, t) { _status("Auditing revision " + d + " of " + t + "…", "#1e40af"); })
        .then(function () { idx = 0; view = "changed"; revising = false; _locatedIdx = -1; _renderStep(); })
        .catch(function (e) {
          eli.log.event("tool", "guided_redlines_audit_failed", { msg: e && e.message });
          idx = 0; _renderStep(); // render with whatever audits landed
        });
    }).catch(function (e) {
      eli.log.event("tool", "guided_redlines_scan_failed", { msg: e && e.message });
      _status("Scan failed: " + (e && e.message || "unknown"), "#b91c1c");
      if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
    });
  }

  // Walk one <w:p> subtree in document order. Returns ordered tokens +
  // resolved (post-accept) and original (pre-change) text.
  function _walkPara(pEl) {
    var tokens = [], resolved = "", original = "", hasRedline = false;
    function rec(node, ctx) {
      var kids = node.childNodes;
      for (var i = 0; i < kids.length; i++) {
        var c = kids[i];
        if (c.nodeType !== 1) continue;
        var ln = c.localName;
        if (ln === "ins") { rec(c, "ins"); }
        else if (ln === "del") { rec(c, "del"); }
        else if (ln === "t") {
          var tx = c.textContent || "";
          resolved += tx;
          if (ctx === "ins") { tokens.push(["ins", tx]); if (tx.trim()) hasRedline = true; }
          else { tokens.push(["norm", tx]); original += tx; }
        } else if (ln === "delText") {
          var dx = c.textContent || "";
          original += dx;
          tokens.push(["del", dx]); if (dx.trim()) hasRedline = true;
        } else { rec(c, ctx); }
      }
    }
    rec(pEl, "norm");
    return { tokens: tokens, resolved: resolved, original: original, hasRedline: hasRedline };
  }
  function _paraStyle(pEl) {
    var prs = pEl.getElementsByTagNameNS(W_NS, "pStyle");
    if (prs && prs.length) {
      return prs[0].getAttributeNS(W_NS, "val") || prs[0].getAttribute("w:val") || "";
    }
    return "";
  }
  function _isHeading(styleVal, text) {
    var sv = String(styleVal || "").toLowerCase();
    if (sv.indexOf("heading") !== -1 || sv === "title") return true;
    var t = String(text || "").trim();
    if (!t) return false;
    return /^(article|section|exhibit|schedule|appendix)\b/i.test(t) || /^\d+(\.\d+)*\s+\S/.test(t);
  }
  function _changesFor(pEl) {
    var out = [];
    function pull(tag, type, textTag) {
      var nodes = pEl.getElementsByTagNameNS(W_NS, tag);
      for (var i = 0; i < nodes.length; i++) {
        var el = nodes[i];
        var tn = el.getElementsByTagNameNS(W_NS, textTag);
        var txt = "";
        for (var j = 0; j < tn.length; j++) txt += tn[j].textContent || "";
        if (!txt.trim()) continue;
        out.push({
          type: type,
          author: el.getAttributeNS(W_NS, "author") || el.getAttribute("w:author") || "",
          date: el.getAttributeNS(W_NS, "date") || el.getAttribute("w:date") || "",
          text: txt,
        });
      }
    }
    pull("ins", "insertion", "t");
    pull("del", "deletion", "delText");
    return out;
  }
  function _parseRevisions(xml) {
    var doc;
    try { doc = new window.DOMParser().parseFromString(xml, "text/xml"); }
    catch (_e) { return []; }
    var ps = doc.getElementsByTagNameNS(W_NS, "p");
    var revs = [], currentHeading = "(preamble)", cur = null, prevWasRedline = false;
    for (var i = 0; i < ps.length; i++) {
      var p = ps[i];
      var w = _walkPara(p);
      var resolvedTrim = w.resolved.trim();
      if (!w.hasRedline) {
        if (_isHeading(_paraStyle(p), resolvedTrim) && resolvedTrim) currentHeading = resolvedTrim.slice(0, 90);
        prevWasRedline = false; cur = null;
        continue;
      }
      var changes = _changesFor(p);
      if (prevWasRedline && cur) {
        cur.tokens.push(["norm", "\n"]);
        cur.tokens = cur.tokens.concat(w.tokens);
        cur.original += "\n" + w.original;
        cur.resolved += "\n" + w.resolved;
        cur.changes = cur.changes.concat(changes);
        cur.paraCount += 1;
      } else {
        // Prefer the redlined paragraph's own leading number (more precise,
        // e.g. 9.2) over the section heading's (e.g. Article 9).
        var clauseNum = _leadingNumber(resolvedTrim) || _leadingNumber(currentHeading);
        cur = {
          section: currentHeading,
          clauseNumber: clauseNum,
          headingTitle: _stripNumber(currentHeading),
          tokens: w.tokens.slice(),
          original: w.original,
          resolved: w.resolved,
          changes: changes,
          paraCount: 1,
          paraIndex: i,
          ai: null,
          guidance: null,
        };
        revs.push(cur);
      }
      prevWasRedline = true;
    }
    return revs;
  }

  // ─── AI audit pool ──────────────────────────────────────────────────
  function _auditPrompt(rev) {
    var changeLines = rev.changes.slice(0, 40).map(function (c) {
      return "- " + c.type.toUpperCase() + (c.author ? " by " + c.author : "") + ": " + (c.text || "").slice(0, 400);
    }).join("\n");
    return [
      "You are a senior Colgate-Palmolive (CP) contracts attorney reviewing redlines the OTHER side returned.",
      "Assess this ONE revision strictly from CP's perspective. CP is the buyer unless the text says otherwise.",
      "",
      "Clause: " + (rev.section || "(unknown)"),
      "",
      "ORIGINAL TEXT (before their changes):",
      (rev.original || "").slice(0, 4000),
      "",
      "THEIR VERSION (after their changes accepted):",
      (rev.resolved || "").slice(0, 4000),
      "",
      "RAW TRACKED CHANGES:",
      changeLines || "(none parsed)",
      "",
      "Return ONLY JSON, no prose:",
      "{",
      '  "items": [ {"severity":"High|Medium|Low","text":"<one material change, plain English>"} ],',
      '  "netImpact": {"direction":"them|us|neutral","score":"High|Medium|Low|None","text":"<one sentence on impact to CP>"},',
      '  "audit": {"severity":"Dealbreaker|Push back|Silent deletion|Cosmetic|Accept","category":"<2-3 words>","deviation":"<one sentence: how it deviates from a balanced/standard clause>","confidence":"High|Medium|Low"},',
      '  "recommendation": "<one sentence: what CP should do>",',
      '  "suggestedRevision": "<counter language CP could propose, full clause text>"',
      "}",
      "items: list EVERY substantive change buried in the paragraph (rewrites often hide several).",
    ].join("\n");
  }
  function _auditRev(rev) {
    if (!eli.ai || typeof eli.ai.complete !== "function") return Promise.resolve();
    return eli.ai.complete(_auditPrompt(rev), { maxTokens: 1300 }).then(function (raw) {
      var parsed = _parseJSON(raw);
      if (parsed) rev.ai = parsed;
    }).catch(function () { /* tolerate — card falls back to raw changes */ });
  }
  function _auditAll(onProgress) {
    return new Promise(function (resolve) {
      var i = 0, done = 0, active = 0, n = revisions.length;
      function next() {
        while (active < AI_CONCURRENCY && i < n) {
          (function () {
            active++;
            _auditRev(revisions[i++]).then(function () {
              active--; done++;
              if (onProgress) onProgress(done, n);
              if (done === n) resolve(); else next();
            });
          })();
        }
      }
      if (!n) resolve(); else next();
    });
  }

  // ─── Optional team-guidance match (review_redlines globals) ──────────
  function _matchGuidance(rev) {
    try {
      if (typeof window._tcSectionKey !== "function" || typeof window._tcLoadForSection !== "function") return null;
      var key = window._tcSectionKey("", "", rev.section || "");
      var rows = window._tcLoadForSection(key) || [];
      return (rows && rows.length) ? rows : null;
    } catch (_e) { return null; }
  }

  // ─── Step render ────────────────────────────────────────────────────
  function _viewPanel(rev) {
    if (view === "marked") {
      var html = rev.tokens.map(function (tk) {
        var t = _esc(tk[1]).replace(/\n/g, "<br>");
        if (tk[0] === "ins") return '<span style="color:#15803d;text-decoration:underline;">' + t + '</span>';
        if (tk[0] === "del") return '<span style="color:#b91c1c;text-decoration:line-through;">' + t + '</span>';
        return t;
      }).join("");
      return '<div style="display:flex;gap:12px;margin-bottom:7px;font-size:11px;color:#64748b;">' +
        '<span><span style="color:#b91c1c;text-decoration:line-through;">struck</span> = removed</span>' +
        '<span><span style="color:#15803d;text-decoration:underline;">underlined</span> = added</span></div>' +
        '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:11px 13px;font-size:12.5px;line-height:1.7;">' + html + '</div>';
    }
    if (view === "side") {
      return '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:#15803d;margin-bottom:4px;">Original (before)</div>' +
        '<div style="background:#e9f6ee;border-radius:8px;padding:11px 13px;font-size:12.5px;line-height:1.65;color:#14532d;margin-bottom:11px;white-space:pre-wrap;">' + _esc(rev.original || "(empty)") + '</div>' +
        '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:#b91c1c;margin-bottom:4px;">Their version (after)</div>' +
        '<div style="background:#fdecec;border-radius:8px;padding:11px 13px;font-size:12.5px;line-height:1.65;color:#7f1d1d;white-space:pre-wrap;">' + _esc(rev.resolved || "(empty)") + '</div>';
    }
    // "What changed" — AI itemized, fallback to raw changes.
    var items = (rev.ai && Array.isArray(rev.ai.items) && rev.ai.items.length) ? rev.ai.items : null;
    if (!items) {
      items = rev.changes.map(function (c) {
        return { severity: "Med", text: (c.type === "insertion" ? "Added: " : "Removed: ") + (c.text || "").slice(0, 160) };
      });
    }
    var rows = items.map(function (it) {
      return '<div style="display:flex;gap:8px;align-items:flex-start;padding:6px 0;border-bottom:1px solid #eef2f6;">' +
        _dot(it.severity) + '<span style="font-size:12.5px;line-height:1.5;">' + _esc(it.text) + '</span></div>';
    }).join("");
    return '<div style="font-size:12px;color:#64748b;margin-bottom:4px;">ELI found <b>' + items.length + ' material change' + (items.length === 1 ? "" : "s") + '</b> in this revision:</div>' + rows;
  }

  function _renderStep() {
    progWrap.style.display = "block";
    footer.style.display = "flex";
    var rev = revisions[idx];
    var chosen = decisions[idx];
    var ai = rev.ai || {};
    var ni = ai.netImpact || {};
    var au = ai.audit || {};
    var ss = _sevStyle(au.severity);
    var authors = {}; rev.changes.forEach(function (c) { if (c.author) authors[c.author] = 1; });
    var authorStr = Object.keys(authors).join(", ") || "unknown";
    var dateStr = ""; for (var k = 0; k < rev.changes.length; k++) { if (rev.changes[k].date) { dateStr = String(rev.changes[k].date).slice(0, 10); break; } }
    if (!rev.guidance) rev.guidance = _matchGuidance(rev);

    var secNum = rev.clauseNumber || "";
    var secDisp = secNum ? (/^\d/.test(secNum) ? "§ " + secNum : secNum) : "";
    var secTitle = rev.headingTitle || rev.section || "(unlabeled clause)";
    var banner = '<div style="background:#fff;border:1px solid #e2e8f0;border-left:4px solid ' + GOLD + ';border-radius:8px;padding:11px 14px;margin-bottom:12px;">' +
      '<div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;">' +
        (secDisp ? '<span style="font-family:Georgia,serif;font-size:18px;font-weight:700;color:' + NAVY + ';">' + _esc(secDisp) + '</span>' : "") +
        '<span style="font-size:14px;font-weight:700;color:#0f172a;">' + _esc(secTitle) + '</span>' +
      '</div>' +
      '<div style="font-size:11px;color:#15803d;margin-top:4px;display:flex;align-items:center;gap:5px;"><span style="width:7px;height:7px;border-radius:50%;background:#15803d;display:inline-block;"></span>Selected in your document</div>' +
    '</div>';

    var meta = '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:11px;">' +
      _pill("#f1f5f9", "#475569", (rev.paraCount > 1 ? "Rewrite · " + rev.paraCount + " paragraphs" : "Revision")) +
      _pill("#e8f1fb", "#1e40af", authorStr) +
      (dateStr ? '<span style="font-size:11px;color:#64748b;">' + _esc(dateStr) + '</span>' : "") + '</div>';

    var seg = '<div style="display:inline-flex;border-radius:8px;overflow:hidden;margin-bottom:10px;border:1px solid #cbd5e1;">' +
      _segBtn("changed", "What changed") + _segBtn("marked", "Marked up") + _segBtn("side", "Side by side") + '</div>';

    var content = '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.07em;color:#94a3b8;margin-bottom:6px;">The revision</div>' +
      seg + '<div style="margin-bottom:13px;">' + _viewPanel(rev) + '</div>';

    function _hdr(t) { return '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.07em;color:#94a3b8;margin-bottom:6px;">' + t + '</div>'; }
    var niBlock = _hdr("Net impact to us") +
      '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:10px 12px;margin-bottom:14px;"><div style="margin-bottom:6px;">' +
        _niBadge(ni.direction) + ' ' + _pill("#f1f5f9", "#475569", "Impact: " + (ni.score || "—")) +
      '</div><div style="font-size:12.5px;line-height:1.55;">' + _esc(ni.text || "Not assessed.") + '</div></div>';
    var auditBlock = _hdr("AI audit") +
      '<div style="background:' + ss.bg + ';border-radius:8px;padding:10px 12px;margin-bottom:14px;"><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px;">' +
        _pill(ss.bg, ss.fg, au.severity || "Review") + _pill("#ffffff", "#475569", au.category || "—") + _pill("#ffffff", "#475569", "Confidence: " + (au.confidence || "—")) +
      '</div><div style="font-size:12.5px;line-height:1.55;color:' + ss.fg + ';">' + _esc(au.deviation || "Switch to “What changed” for the itemized list.") + '</div></div>';
    var guidanceBlock = _hdr("Team guidance") +
      '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:10px 12px;margin-bottom:14px;font-size:12.5px;line-height:1.6;color:' + (rev.guidance ? "#1e293b" : "#94a3b8") + ';">' +
        (rev.guidance ? rev.guidance.map(function (g) { return '<div style="margin-bottom:4px;"><b>' + _esc(g.authorName || "team") + ':</b> ' + _esc(g.text || "") + '</div>'; }).join("") : "No matching team guidance. (Open Review Redlines once to sync the library.)") +
      '</div>';

    var recBar = chosen
      ? '<div style="display:flex;align-items:center;gap:8px;background:#e9f6ee;border-radius:8px;padding:9px 12px;margin-top:4px;"><span style="color:#15803d;font-weight:800;">✓</span><span style="font-size:12.5px;"><b>Your call:</b> ' + _esc(chosen) + '</span></div>'
      : '<div style="display:flex;align-items:center;gap:8px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:9px 12px;margin-top:4px;"><span style="width:8px;height:8px;border-radius:50%;background:' + GOLD + ';flex-shrink:0;"></span><span style="font-size:12.5px;line-height:1.5;"><b>ELI recommends:</b> ' + _esc(ai.recommendation || "Review this revision.") + '</span></div>';

    var actions;
    if (revising) {
      var pre = (decisions[idx] === "Revised" && rev._revText != null) ? rev._revText : (ai.suggestedRevision || rev.original || "");
      actions = '<div style="margin-top:12px;border:1px solid #cbd5e1;border-radius:8px;padding:11px;">' +
        '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.07em;color:#94a3b8;margin-bottom:5px;">Revise — ELI’s counter language (edit freely)</div>' +
        '<textarea id="grdRev" style="width:100%;box-sizing:border-box;min-height:120px;padding:8px 10px;font-size:12.5px;line-height:1.6;font-family:inherit;border:1px solid #cbd5e1;border-radius:8px;resize:vertical;">' + _esc(pre) + '</textarea>' +
        '<div style="display:flex;gap:7px;justify-content:flex-end;margin-top:9px;">' +
          '<button id="grdRevCancel" style="font-size:12px;font-weight:600;padding:7px 13px;border-radius:8px;border:1px solid #cbd5e1;background:#fff;color:#475569;cursor:pointer;">Cancel</button>' +
          '<button id="grdRevApply" style="font-size:12px;font-weight:800;padding:7px 15px;border-radius:8px;border:none;background:' + GOLD + ';color:' + GOLDTX + ';cursor:pointer;">Save revision</button>' +
        '</div></div>';
    } else {
      actions = '<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:12px;">' +
        _actBtn("grdAccept", "Accept", false) + _actBtn("grdReject", "Reject", false) + _actBtn("grdRevise", "Revise", true) + '</div>';
    }

    // Full-width banner + meta, then two columns: left = the revision +
    // decision; right = net impact / AI audit / guidance.
    body.innerHTML = banner + meta +
      '<div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:start;">' +
        '<div>' + content + recBar + actions + '</div>' +
        '<div>' + niBlock + auditBlock + guidanceBlock + '</div>' +
      '</div>';
    body.scrollTop = 0;

    barEl.style.width = Math.round(((idx + 1) / revisions.length) * 100) + "%";
    labelEl.textContent = "Revision " + (idx + 1) + " of " + revisions.length;
    decidedEl.textContent = decisions.filter(Boolean).length + " decided";
    posEl.textContent = "";
    backBtn.style.visibility = idx === 0 ? "hidden" : "visible";
    nextBtn.style.visibility = "visible";
    nextBtn.textContent = (idx === revisions.length - 1) ? "Finish →" : "Next →";

    // Drive Word's selection to this clause — only when the revision
    // changes, not on tab toggles / revise open (those re-render too).
    if (_locatedIdx !== idx) { _locatedIdx = idx; _locate(rev); }

    box.querySelectorAll("[data-seg]").forEach(function (b) { b.onclick = function () { view = b.getAttribute("data-seg"); _renderStep(); }; });
    var ac = box.querySelector("#grdAccept"), rj = box.querySelector("#grdReject"), rv = box.querySelector("#grdRevise");
    if (ac) ac.onclick = function () { decisions[idx] = "Accepted"; rev._revText = null; _adv(); };
    if (rj) rj.onclick = function () { decisions[idx] = "Rejected"; rev._revText = null; _adv(); };
    if (rv) rv.onclick = function () { revising = true; _renderStep(); };
    var rc = box.querySelector("#grdRevCancel"), ra = box.querySelector("#grdRevApply");
    if (rc) rc.onclick = function () { revising = false; _renderStep(); };
    if (ra) ra.onclick = function () {
      var ta = box.querySelector("#grdRev");
      rev._revText = ta ? ta.value : "";
      decisions[idx] = "Revised";
      revising = false; _adv();
    };
  }
  function _segBtn(v, label) {
    var on = view === v;
    return '<button data-seg="' + v + '" style="font-size:11.5px;font-weight:600;padding:6px 11px;border:none;border-right:1px solid #cbd5e1;cursor:pointer;background:' + (on ? NAVY : "#fff") + ';color:' + (on ? "#fff" : "#64748b") + ';">' + label + '</button>';
  }
  function _actBtn(id, label, gold) {
    return '<button id="' + id + '" style="font-size:12.5px;font-weight:700;padding:9px 16px;border-radius:8px;cursor:pointer;border:1px solid ' +
      (gold ? GOLD : "#cbd5e1") + ';background:' + (gold ? GOLD : "#fff") + ';color:' + (gold ? GOLDTX : "#1e293b") + ';">' + label + '</button>';
  }
  function _adv() { revising = false; view = "changed"; if (idx < revisions.length - 1) { idx++; _renderStep(); } else _renderDone(); }

  // ─── Done + brief ───────────────────────────────────────────────────
  function _renderDone() {
    barEl.style.width = "100%";
    labelEl.textContent = "Review complete";
    decidedEl.textContent = decisions.filter(Boolean).length + " of " + revisions.length + " decided";
    backBtn.style.visibility = "visible";
    nextBtn.style.visibility = "hidden";
    var rows = revisions.map(function (r, i) {
      var d = decisions[i] || "Not decided";
      return '<div style="display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid #eef2f6;font-size:12.5px;"><span style="color:#475569;">' + _esc(r.section || "") + '</span><span style="font-weight:700;">' + _esc(d) + '</span></div>';
    }).join("");
    body.innerHTML =
      '<div style="text-align:center;padding:6px 0 12px;"><div style="font-size:30px;color:#15803d;line-height:1;">✓</div>' +
      '<div style="font-family:Georgia,serif;font-size:18px;margin-top:6px;">All revisions handled</div>' +
      '<div style="font-size:12.5px;color:#64748b;margin-top:3px;">Every tracked change in the document was reviewed.</div></div>' + rows +
      '<div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:16px;">' +
        '<button id="grdBrief" style="font-size:12.5px;font-weight:800;padding:9px 16px;border-radius:8px;border:none;background:' + GOLD + ';color:' + GOLDTX + ';cursor:pointer;">Generate negotiation brief</button>' +
        '<button id="grdRestart" style="font-size:12.5px;font-weight:600;padding:9px 16px;border-radius:8px;border:1px solid #cbd5e1;background:#fff;color:#475569;cursor:pointer;">Start over</button>' +
      '</div><div id="grdBriefOut" style="margin-top:14px;"></div>';
    box.querySelector("#grdRestart").onclick = function () { idx = 0; view = "changed"; revising = false; _locatedIdx = -1; decisions = revisions.map(function () { return null; }); _renderStep(); };
    box.querySelector("#grdBrief").onclick = _genBrief;
  }
  function _genBrief() {
    var out = box.querySelector("#grdBriefOut");
    var btn = box.querySelector("#grdBrief");
    if (btn) { btn.disabled = true; btn.style.opacity = "0.55"; }
    if (out) out.innerHTML = '<div style="color:#64748b;font-style:italic;font-size:12.5px;text-align:center;padding:10px;">Drafting brief…</div>';
    var lines = revisions.map(function (r, i) {
      var ai = r.ai || {};
      return "Clause: " + (r.section || "(unknown)") +
        "\nDecision: " + (decisions[i] || "not decided") +
        "\nImpact: " + ((ai.netImpact && ai.netImpact.text) || "n/a") +
        (r._revText ? "\nOur counter: " + r._revText.slice(0, 600) : "");
    }).join("\n\n");
    var prompt = [
      "You are a senior Colgate-Palmolive contracts attorney. Write a concise negotiation brief for an internal colleague based on these redline decisions.",
      "Group into: (1) Dealbreakers we are rejecting, (2) Points we are pushing back on with our position, (3) Items accepted. Be specific and brief. Plain prose with short headers.",
      "",
      lines,
    ].join("\n");
    eli.ai.complete(prompt, { maxTokens: 1600 }).then(function (raw) {
      var safe = _esc(raw || "(empty)").replace(/\n/g, "<br>");
      if (out) out.innerHTML = '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;font-size:12.5px;line-height:1.65;">' + safe + '</div>';
      if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
    }).catch(function (e) {
      if (out) out.innerHTML = '<div style="color:#b91c1c;font-size:12.5px;">Brief failed: ' + _esc(e && e.message || "unknown") + '</div>';
      if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
    });
  }

  backBtn.onclick = function () { if (idx > 0) { idx--; view = "changed"; revising = false; _renderStep(); } };
  nextBtn.onclick = function () { if (idx < revisions.length - 1) { idx++; view = "changed"; revising = false; _renderStep(); } else _renderDone(); };

  _renderStart();
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedGuidedRedlines"); } catch (e) {}
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    if (typeof window.showGuidedRedlines !== "function") {
      eli.log.event("tool", "guided_redlines_fn_missing", {});
      if (typeof showToast === "function") showToast("Guided Redlines failed to load", "err");
      return;
    }
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    try { window.showGuidedRedlines(eli); }
    catch (e) {
      eli.log.event("tool", "guided_redlines_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_guided_redlines: _show },
    guided_redlines: { open: _show },
  });

  eli.log.event("tool", "guided_redlines_initialized", {});
}
